function GlobalLightbox(){
  const [data, setData] = q.useState({ open: false, src: "", title: "", subtitle: "" });
  const [zoom, setZoom] = q.useState(1);

  q.useEffect(() => {
    window.openLightbox = (src, title = "", subtitle = "") => {
      if (!src) return;
      setZoom(1);
      setData({ open: true, src, title, subtitle });
    };

    const handleClick = (e) => {
      const el = e.target;
      if (el && el.tagName === "IMG") {
        if (el.width < 40 && el.height < 40) return;
        if (el.closest(".no-lightbox")) return;
        const fullSrc = el.getAttribute("data-hd-src") || el.currentSrc || el.src;
        if (!fullSrc) return;
        const title = el.alt || el.getAttribute("data-title") || "HD Preview";
        const subtitle = el.getAttribute("data-badge") || "High Definition • 4K UHD Master";
        window.openLightbox(fullSrc, title, subtitle);
      }
    };

    const handleKey = (e) => {
      if (e.key === "Escape") {
        setData(d => ({ ...d, open: false }));
        setZoom(1);
      }
    };

    window.addEventListener("click", handleClick);
    window.addEventListener("keydown", handleKey);
    return () => {
      window.removeEventListener("click", handleClick);
      window.removeEventListener("keydown", handleKey);
    };
  }, []);

  if (!data.open || !data.src) return null;

  return m.jsxs("div", {
    className: "fixed inset-0 z-[99999] bg-black/92 backdrop-blur-2xl flex flex-col items-center justify-between p-4 md:p-6 select-none animate-fadeIn",
    onClick: (e) => {
      if (e.target === e.currentTarget || e.target.id === "lightbox-backdrop") {
        setData(d => ({ ...d, open: false }));
        setZoom(1);
      }
    },
    id: "lightbox-backdrop",
    children: [
      m.jsxs("div", {
        className: "w-full max-w-7xl flex items-center justify-between z-10",
        children: [
          m.jsxs("div", {
            className: "flex items-center space-x-3",
            children: [
              m.jsx("span", {
                className: "px-3 py-1 rounded-full text-[10px] font-mono font-bold bg-cyan-500/20 text-cyan-300 border border-cyan-400/40",
                children: "4K ULTRA HD ENLARGED VIEW"
              }),
              data.title && m.jsx("h4", { className: "text-xs md:text-sm font-bold text-slate-200 truncate max-w-xs md:max-w-md", children: data.title })
            ]
          }),
          m.jsxs("div", {
            className: "flex items-center space-x-2",
            children: [
              m.jsx("button", {
                type: "button",
                onClick: (e) => { e.stopPropagation(); setZoom(z => (z === 1 ? 1.6 : z === 1.6 ? 2.2 : 1)); },
                className: "px-3 py-1.5 rounded-xl bg-white/10 hover:bg-white/20 text-slate-200 border border-white/20 text-xs font-mono font-semibold transition-all flex items-center space-x-1",
                children: [m.jsx("span", { children: "🔍" }), m.jsx("span", { children: `${zoom}x` })]
              }),
              m.jsx("button", {
                type: "button",
                onClick: (e) => { e.stopPropagation(); setData(d => ({ ...d, open: false })); setZoom(1); },
                className: "w-9 h-9 rounded-full bg-rose-500/20 hover:bg-rose-500/40 text-rose-300 border border-rose-500/40 flex items-center justify-center text-sm font-bold shadow-lg shadow-rose-500/20 transition-all",
                title: "Close (ESC)",
                children: "✕"
              })
            ]
          })
        ]
      }),
      m.jsx("div", {
        className: "flex-grow flex items-center justify-center w-full max-w-7xl overflow-hidden my-auto py-2",
        onClick: (e) => {
          if (e.target === e.currentTarget) {
            setData(d => ({ ...d, open: false }));
            setZoom(1);
          }
        },
        children: m.jsx("img", {
          src: data.src,
          alt: data.title || "Full Preview",
          style: { transform: `scale(${zoom})`, transition: "transform 0.25s ease-out" },
          className: "max-h-[82vh] max-w-[95vw] object-contain rounded-2xl shadow-2xl border border-white/10 cursor-zoom-in",
          onClick: (e) => {
            e.stopPropagation();
            setZoom(z => (z === 1 ? 1.6 : z === 1.6 ? 2.2 : 1));
          }
        })
      }),
      m.jsxs("div", {
        className: "w-full max-w-md text-center py-2 px-4 rounded-2xl bg-slate-900/80 border border-white/10 backdrop-blur-md flex items-center justify-between text-[11px] font-mono text-slate-400 z-10",
        children: [
          m.jsx("span", { children: data.subtitle || "Click image to Zoom • Press ESC to Close" }),
          m.jsx("span", { className: "text-cyan-400 font-bold", children: "✓ Uncompressed" })
        ]
      })
    ]
  });
}

